  -- Kestrel registers
  r_arg1 real := arg1;
  r_arg2 text := arg2;
  r_arg3 real := arg3;
  r_arg4 text := arg4;
  result_val real;
  status_text text;
BEGIN
  -- RAM case
  IF r_arg1 < 0 THEN
    result_val := r_arg1 * (-1);

    UPDATE chip_model
    SET RAM_MiB = result_val
    WHERE WiFi = r_arg2;

  ELSIF r_arg1 < 10 THEN
    result_val := r_arg1 + 5;

    DELETE FROM chip_model
    WHERE RAM_MiB = r_arg1;

  ELSIF r_arg1 < 20 THEN
    result_val := r_arg1 * 2;

    UPDATE screen_mode
    SET used_kb = r_arg3 + result_val
    WHERE Pixels = r_arg4;

  ELSIF r_arg1 < 30 THEN
    result_val := r_arg1 - 8;

    DELETE FROM screen_mode
    WHERE used_kb = r_arg3;

  ELSE
    result_val := r_arg1 / 2;
    status_text := 'processed';
  END IF;

  -- 1
  UPDATE phone p
  SET Accreditation_level = p.Accreditation_level || '_screen_match'
  WHERE EXISTS (
    SELECT 1
    FROM screen_mode sm
    WHERE sm.Pixels = r_arg4
