  UPDATE phone AS p
  SET "Accreditation_level" = COALESCE(p."Accreditation_level", '') || '_screen_match'
  WHERE EXISTS (
    SELECT 1
    FROM screen_mode AS sm
    WHERE sm."Pixels" = r_arg4
      AND sm."used_kb" = r_arg3
      AND p."screen_mode" = (sm."Graphics_mode")::text
  );

  -- 2
  UPDATE phone AS p
  SET "Accreditation_type" = COALESCE(p."Accreditation_type", '') || '_wifi_match'
  WHERE EXISTS (
    SELECT 1
    FROM chip_model AS cm
    WHERE cm."WiFi" = r_arg2
      AND p."chip_model" = cm."Model_name"
  );

  -- 3
  UPDATE phone AS p
  SET "Hardware_Model_name" = COALESCE(p."Hardware_Model_name", '') || '_ram_wifi_match'
  WHERE EXISTS (
    SELECT 1
    FROM chip_model AS cm
    WHERE cm."RAM_MiB" = r_arg1
      AND cm."WiFi" = r_arg2
      AND p."chip_model" = cm."Model_name"
  );

  -- 4
  UPDATE phone AS p
  SET "Accreditation_type" = COALESCE(p."Accreditation_type", '') || '_dual_match'
  WHERE EXISTS (
    SELECT 1
    FROM chip_model AS cm
    WHERE cm."WiFi" = r_arg2
      AND p."chip_model" = cm."Model_name"
  )
  AND EXISTS (
    SELECT 1
    FROM screen_mode AS sm
    WHERE sm."Pixels" = r_arg4
      AND p."screen_mode" = (sm."Graphics_mode")::text
  );

  -- 5
  UPDATE chip_model
  SET "WiFi" = r_arg2 || status_text
  WHERE "RAM_MiB" = r_arg1;

  -- 6
  result_val := result_val + 3;

  -- 7
  UPDATE screen_mode
  SET "Pixels" = r_arg4 || '_updated'
  WHERE "used_kb" = r_arg3;

  -- 8
  DELETE FROM chip_model
  WHERE "RAM_MiB" > result_val;

  -- 9
  status_text := 'active';

  -- 10
  UPDATE screen_mode
  SET "used_kb" = r_arg3 + 12
  WHERE "Pixels" = r_arg4;

  -- 11
  UPDATE chip_model
  SET "RAM_MiB" = result_val
  WHERE "WiFi" = r_arg2;

  -- 12
  result_val := result_val - 7;

  -- 13
  DELETE FROM screen_mode
  WHERE "Pixels" = r_arg4 || '_old';

  -- 14
  UPDATE chip_model
  SET "WiFi" = r_arg2 || '_final'
  WHERE "RAM_MiB" = r_arg1;

  -- 15
  status_text := 'completed';

  -- 16
  UPDATE screen_mode
  SET "used_kb" = r_arg3 * 3
  WHERE "Pixels" = r_arg4;

  -- 17
  DELETE FROM chip_model
  WHERE "WiFi" = r_arg2 || status_text;
END;
$$;
